1. using Microsoft.ML;
2. using Microsoft.ML.Data;
3. using Microsoft.Extensions.ML;
4. 
5. var builder = WebApplication.CreateBuilder(args);
6. 
7. // Train the model and register the prediction engine pool
8. var mlContext = new MLContext(seed: 42);
9. var dataPath = Path.Combine(AppContext.BaseDirectory, "..", "..", "..", "Data", "customers.csv");
10. var dataView = mlContext.Data.LoadFromTextFile<CustomerData>(dataPath, hasHeader: true, separatorChar: ',');
11. 
12. // Map "Yes"/"No" to true/false using a lookup table
13. var lookupData = new[] {
14.     new LabelLookup { Churned = "Yes", Label = true },
15.     new LabelLookup { Churned = "No", Label = false }
16. };
17. var lookupView = mlContext.Data.LoadFromEnumerable(lookupData);
18. 
19. var pipeline = mlContext.Transforms.Conversion.MapValue(
20.         "Label", lookupView, lookupView.Schema["Churned"], lookupView.Schema["Label"], inputColumnName: nameof(CustomerData.Churned))
21.     .Append(mlContext.Transforms.Categorical.OneHotEncoding("RegionEncoded", nameof(CustomerData.Region)))
22.     .Append(mlContext.Transforms.Concatenate("Features", nameof(CustomerData.Age), nameof(CustomerData.Income), "RegionEncoded", nameof(CustomerData.PurchaseHistory)))
23.     .Append(mlContext.Transforms.NormalizeMinMax("Features"))
24.     .Append(mlContext.BinaryClassification.Trainers.SdcaLogisticRegression(
25.         labelColumnName: "Label", featureColumnName: "Features"));
26. 
27. var rowCount = (int)dataView.GetColumn<string>("Churned").Count();
28. 
29. ITransformer model;
30. if (rowCount >= 10)
31. {
32.     var split = mlContext.Data.TrainTestSplit(dataView, testFraction: 0.2);
33.     model = pipeline.Fit(split.TrainSet);
34.     var predictions = model.Transform(split.TestSet);
35.     var metrics = mlContext.BinaryClassification.Evaluate(predictions, labelColumnName: "Label");
36.     Console.WriteLine($"Model trained — AUC: {metrics.AreaUnderRocCurve:F4}, Accuracy: {metrics.Accuracy:F4}, F1: {metrics.F1Score:F4}");
37. }
38. else
39. {
40.     // Dataset too small for a meaningful train/test split; train on all data
41.     model = pipeline.Fit(dataView);
42.     Console.WriteLine($"Model trained on {rowCount} rows (dataset too small for evaluation split).");
43. }
44. 
45. // Save model and register pooled prediction engine
46. var modelPath = Path.Combine(AppContext.BaseDirectory, "ChurnModel.zip");
47. mlContext.Model.Save(model, dataView.Schema, modelPath);
48. 
49. builder.Services.AddPredictionEnginePool<CustomerData, ChurnPrediction>()
50.     .FromFile(modelPath);
51. 
52. var app = builder.Build();
53. 
54. app.MapPost("/predict", (PredictionEnginePool<CustomerData, ChurnPrediction> pool, CustomerData input) =>
55. {
56.     var prediction = pool.Predict(input);
57.     return Results.Ok(new
58.     {
59.         WillChurn = prediction.PredictedLabel,
60.         Probability = prediction.Probability
61.     });
62. });
63. 
64. app.Run();
65. 
66. public class CustomerData
67. {
68.     [LoadColumn(0)]
69.     public float Age { get; set; }
70. 
71.     [LoadColumn(1)]
