 using Microsoft.ML;
 using Microsoft.ML.Data;
 using Microsoft.Extensions.ML;

 var builder = WebApplication.CreateBuilder(args);

 // Train the model and register the prediction engine pool
 var mlContext = new MLContext(seed: 42);
 var dataPath = Path.Combine(AppContext.BaseDirectory, "..", "..", "..", "Data", "customers.csv");
 var dataView = mlContext.Data.LoadFromTextFile<CustomerData>(dataPath, hasHeader: true, separatorChar: ',');

 // Map "Yes"/"No" to true/false using a lookup table
 var lookupData = new[] {
     new LabelLookup { Churned = "Yes", Label = true },
     new LabelLookup { Churned = "No", Label = false }
 };
 var lookupView = mlContext.Data.LoadFromEnumerable(lookupData);

 var pipeline = mlContext.Transforms.Conversion.MapValue(
         "Label", lookupView, lookupView.Schema["Churned"], lookupView.Schema["Label"], inputColumnName: nameof(CustomerData.Churned))
     .Append(mlContext.Transforms.Categorical.OneHotEncoding("RegionEncoded", nameof(CustomerData.Region)))
     .Append(mlContext.Transforms.Concatenate("Features", nameof(CustomerData.Age), nameof(CustomerData.Income), "RegionEncoded", nameof(CustomerData.PurchaseHistory)))
     .Append(mlContext.Transforms.NormalizeMinMax("Features"))
     .Append(mlContext.BinaryClassification.Trainers.SdcaLogisticRegression(
         labelColumnName: "Label", featureColumnName: "Features"));

 var rowCount = (int)dataView.GetColumn<string>("Churned").Count();

 ITransformer model;
 if (rowCount >= 10)
 {
     var split = mlContext.Data.TrainTestSplit(dataView, testFraction: 0.2);
     model = pipeline.Fit(split.TrainSet);
     var predictions = model.Transform(split.TestSet);
     var metrics = mlContext.BinaryClassification.Evaluate(predictions, labelColumnName: "Label");
     Console.WriteLine($"Model trained — AUC: {metrics.AreaUnderRocCurve:F4}, Accuracy: {metrics.Accuracy:F4}, F1: {metrics.F1Score:F4}");
 }
 else
 {
     // Dataset too small for a meaningful train/test split; train on all data
     model = pipeline.Fit(dataView);
     Console.WriteLine($"Model trained on {rowCount} rows (dataset too small for evaluation split).");
 }

 // Save model and register pooled prediction engine
 var modelPath = Path.Combine(AppContext.BaseDirectory, "ChurnModel.zip");
 mlContext.Model.Save(model, dataView.Schema, modelPath);

 builder.Services.AddPredictionEnginePool<CustomerData, ChurnPrediction>()
     .FromFile(modelPath);

 var app = builder.Build();

 app.MapPost("/predict", (PredictionEnginePool<CustomerData, ChurnPrediction> pool, CustomerData input) =>
 {
     var prediction = pool.Predict(input);
     return Results.Ok(new
     {
         WillChurn = prediction.PredictedLabel,
         Probability = prediction.Probability
     });
 });

 app.Run();

